import{_ as r,o as d,c as e,a2 as o}from"./chunks/framework.BXzK3EA4.js";const b=JSON.parse('{"title":"크로스 게임 종합: 치 디멘션 비교 매트릭스 — 잔선: 서울 설계용","description":"","frontmatter":{},"headers":[],"relativePath":"rules/Ref-Cross-Synthesis.md","filePath":"rules/Ref-Cross-Synthesis.md"}'),a={name:"rules/Ref-Cross-Synthesis.md"};function s(n,t,h,l,i,g){return d(),e("div",null,[...t[0]||(t[0]=[o('<div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p></div><blockquote><p>출처 인계: <a href="https://github.com/islee23520/seoul-kenshi/blob/docs/reference-context-sync-st_01a079f1/.omo/research/README.md" target="_blank" rel="noreferrer">공유 조사 색인</a>. 로컬 sources.json·원문 패킷 언급은 조사 당시 기록이며 이 전달에 원시 자료가 포함된다는 뜻이 아니다. 누락된 ID는 미확인으로 남긴다. 자동 생성 문서입니다 — 원본은 저장소 내부 조사 문서(<code>CROSS-GAME-SYNTHESIS.md</code>)에서 파생했으며 금지 용어는 위키 공개 기준에 맞게 치환했다.</p></blockquote><h1 id="크로스-게임-종합-치-디멘션-비교-매트릭스-—-잔선-서울-설계용" tabindex="-1">크로스 게임 종합: 치 디멘션 비교 매트릭스 — 잔선: 서울 설계용 <a class="header-anchor" href="#크로스-게임-종합-치-디멘션-비교-매트릭스-—-잔선-서울-설계용" aria-label="Permalink to &quot;크로스 게임 종합: 치 디멘션 비교 매트릭스 — 잔선: 서울 설계용&quot;">​</a></h1><ul><li>작성일: 2026-09-06 / 작업: st_01a0778b (Grok-4)</li><li>근거: 로컬 문서 재사용 전용(REPORT.md [S01–S14], ck3-ui-reference.md [S19–S33], bb-ui-reference.md [S40–S50·S70], 내부 종합 조사 문서 [S80–S108], genre-map-structure.md [S60–S74]). 이 문서는 새 웹 페치를 하지 않았다.</li><li>표기: <strong>[문서]</strong> 원문에 설명됨 / <strong>[추론]</strong> 구조 해석 / <strong>[적용 제안]</strong> 잔선 설계 권고 / <strong>[미확인]</strong> 자료로 확정 불가.</li><li>대상 게임: 켄시(K-시스템), 배틀 브라더즈(Battle Brothers), 크루세이더 킹스 3(CK3), 파이어 엠블럼 각성(FE), 파이널 판타지 택틱스(FFT), 택틱스 오우거 리본(TO), 트라이앵글 스트래터지(Triangle), 랑그리사 I·II(Langrisser), 파랜드 택틱스 1·2(파랜드), 창세기전 2·회색의 잔영(창세기전).</li></ul><h2 id="_0-요약" tabindex="-1">0. 요약 <a class="header-anchor" href="#_0-요약" aria-label="Permalink to &quot;0. 요약&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>차원</th><th>최고 모델</th><th>잔선 권고 한 줄</th></tr></thead><tbody><tr><td>1</td><td>무에서 시작</td><td>K-시스템</td><td>결핍의 종류(현금·노동력·시장접근·신체·적대)를 축으로 시작 설계; 밴드 3인+손수레+3일 식량</td></tr><tr><td>2</td><td>경제 압박 루프</td><td>Battle Brothers</td><td>확정한 이동·휴식만 시간 진행; 식량+계약 인력 수당+회복 비용의 3중 압박</td></tr><tr><td>3</td><td>사망/부상 처리</td><td>Battle Brothers(+K-시스템)</td><td>회복 가능한 실패: 쓰러짐≠사망, 부상은 인물에 남고 정산 영수증에 표시</td></tr><tr><td>4</td><td>전략↔전술 연결</td><td>Battle Brothers / FFT</td><td>세 지도(노선도·역간 이동·역 내부 전장)를 다른 질문·시간·통제권으로 분리</td></tr><tr><td>5</td><td>세계 진화·반응</td><td>K-시스템(World States)+BB(위기)</td><td>핵심 인물 상태 전이 + 지역 상황 변화의 두 속도; 전면 시뮬레이션 AI 금지</td></tr><tr><td>6</td><td>난이도 철학</td><td>Triangle(저항 실패 보존)+FE(모드 분리)</td><td>무레벨스케일링(K-시스템) + 실패 시 진척 보존 옵션(Triangle) 병용</td></tr><tr><td>7</td><td>포획/모집</td><td>K-시스템(구조·가입비)+BB(포로 충원)</td><td>구조→신뢰→가입의 관계 기반 모집; 즉시 돈으로 사는 병력은 계약 인력으로 분리</td></tr></tbody></table><hr><h2 id="_1-무에서-시작-start-from-nothing" tabindex="-1">1. 무에서 시작(start from nothing) <a class="header-anchor" href="#_1-무에서-시작-start-from-nothing" aria-label="Permalink to &quot;1. 무에서 시작(start from nothing)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>게임</th><th>시작 구조</th><th>근거</th></tr></thead><tbody><tr><td><strong>K-시스템</strong></td><td>13개 기본 시작. 결핍 축이 다양: 현금/매각자산/노동력/먹는 입/전투 숙련/합법 시장 접근/신체 손상(Rock Bottom은 왼팔 없음)/개시 적대(Holy Nation -100)·현상금. 0c인 Trader와 0c인 Rock Bottom은 전혀 다른 경제. 난이도 표기는 이후 성장 배율에 영향 없음</td><td>[문서: S82, S83]</td></tr><tr><td><strong>Battle Brothers</strong></td><td>15개 기원. 시작 보너스가 아니라 장기 규칙: Peasant Militia(16인 출전·Lowborn만 고용), Lone Wolf(1인 사망 시 종료), Trading Caravan(매매 유리·명성 획득 66%), Manhunters(포로 충원·비율 의무) 등</td><td>[문서: S96, S98]</td></tr><tr><td><strong>CK3</strong></td><td>플레이어는 군주·가문에서 시작. &#39;무(無)&#39;가 아니라 &#39;상속받은 부담&#39;에서 시작</td><td>[문서: S19, S30]</td></tr><tr><td><strong>FE 각성</strong></td><td>서사 지정 시작. 챕터 진행형</td><td>[문서: S01]</td></tr><tr><td><strong>FFT</strong></td><td>직업·잡지로 시작. 파견·모집이 있는 도시 경제로 진입</td><td>[문서: S02 pp.25–39]</td></tr><tr><td><strong>Triangle / 파랜드 / 창세기전 / Langrisser / TO</strong></td><td>모두 서사·챕터 지정 시작. Triangle은 신념 축이 초기 분기</td><td>[문서: S05–S09, S11]</td></tr></tbody></table><p><strong>최고: K-시스템</strong> — &#39;무에서 시작&#39;을 단일 난이도가 아니라 <strong>결핍의 조합</strong>으로 설계.</p><p><strong>잔선 권고 [적용 제안]:</strong> 기본 기원은 &#39;공동 피난에서 살아남은 3인 밴드&#39; — 안전한 B1 공용 대합실 임시 잠자리, 손수레 1대, 약 3일분 식량. 결핍은 &#39;안정 식량 수입·긴 휴식 권리·적재량·신뢰 거래처&#39;.</p><hr><h2 id="_2-경제-압박-루프" tabindex="-1">2. 경제 압박 루프 <a class="header-anchor" href="#_2-경제-압박-루프" aria-label="Permalink to &quot;2. 경제 압박 루프&quot;">​</a></h2><table tabindex="0"><thead><tr><th>게임</th><th>압박 구조</th><th>근거</th></tr></thead><tbody><tr><td><strong>Battle Brothers</strong></td><td>매일 급료+식량(1인당 하루 2, 부패 기한)+수리·의약·탄약. 지도 시간이 흐르는 동안에만 비용 발생. 계약 순이익 = 완료금+전리품 − 여행/회복 기간 급료 − 보급 − 대체 고용</td><td>[문서: S47, S97, S102–S105]</td></tr><tr><td><strong>K-시스템</strong></td><td>허기 시간 소모, 200 미만 영양실조→능력 저하→실신·사망. 악순환: 굶음→느려짐→습격 회피 실패→부상→수입 중단</td><td>[문서: S84–S86]</td></tr><tr><td><strong>CK3</strong></td><td>금·세금·병력 유지비. 압박이 개인 서사(스트레스)와 결합</td><td>[문서: S19–S21]</td></tr><tr><td><strong>FFT</strong></td><td>파견은 비용·기간·적자 가능성 명시. 월드 1구간=1일</td><td>[문서: S02 pp.25–29]</td></tr></tbody></table><p><strong>최고: Battle Brothers</strong> — 시간 자체가 비용이고, 모든 여행·회복·대기가 손익 계산에 들어간다.</p><p><strong>잔선 권고 [적용 제안]:</strong> 압박 3종 = 공동 식량 일일 소모 + 계약 인력 수당 + 안전한 회복의 시간·비용. 확정한 이동·휴식·작업만 캠페인 시간 진행. 저수익 안전 작업과 고수익 위험 작업 병존.</p><hr><h2 id="_3-캐릭터-사망-부상-처리" tabindex="-1">3. 캐릭터 사망/부상 처리 <a class="header-anchor" href="#_3-캐릭터-사망-부상-처리" aria-label="Permalink to &quot;3. 캐릭터 사망/부상 처리&quot;">​</a></h2><table tabindex="0"><thead><tr><th>게임</th><th>처리</th><th>근거</th></tr></thead><tbody><tr><td><strong>K-시스템</strong></td><td>쓰러짐≠사망. 부위별 HP, 절단→의수·의족. 패배가 노예화·납치로 이어져도 플레이 계속 — 당한 일 자체가 다음 목표 생성</td><td>[문서: S83, S84, S86, S87, S94]</td></tr><tr><td><strong>Battle Brothers</strong></td><td>영구 부상 = 능력치 영구 감소, 전투 후 결과 화면 확정 표시. 사망은 사망</td><td>[문서: wt-Permanent-Injuries, wt-Morale; S98]</td></tr><tr><td><strong>FE 각성</strong></td><td>Classic=영구사망, Casual=해당 전투에서만 퇴각. 주인공 사망은 게임오버</td><td>[문서: S01 §14]</td></tr><tr><td><strong>Triangle</strong></td><td>영구사망 없음, 패배·퇴각해도 EXP/Kudos 보존</td><td>[문서: S07]</td></tr></tbody></table><p><strong>최고: Battle Brothers(+K-시스템)</strong> — BB는 &#39;결과가 인물에 남는다&#39;를 정산 UI까지 일관, K-시스템는 &#39;실패 후에도 선택과 진척이 남는다&#39;를 극한까지.</p><p><strong>잔선 권고 [적용 제안]:</strong> 사망 계층 3단계 — ①쓰러짐(전투 불능, 회복 가능) ②부상(다음 원정·전투 시작 상태에 이어짐, 정산 영수증 표시) ③사망(명시적 규칙이 있는 행동에서만). 현재 POC의 &#39;HP 7 → 다음 전투 10 초기화&#39;가 바로 고칠 지점.</p><hr><h2 id="_4-전략-계층-↔-전술-계층-연결" tabindex="-1">4. 전략 계층 ↔ 전술 계층 연결 <a class="header-anchor" href="#_4-전략-계층-↔-전술-계층-연결" aria-label="Permalink to &quot;4. 전략 계층 ↔ 전술 계층 연결&quot;">​</a></h2><table tabindex="0"><thead><tr><th>게임</th><th>구조</th><th>근거</th></tr></thead><tbody><tr><td><strong>Battle Brothers</strong></td><td>전역 지도(전략+여행 통합) → 육각 전장. <strong>접촉 지형이 전술 지형을 제약</strong>. 진형 슬롯이 시작 위치</td><td>[문서: S40–S42, S45, S50]</td></tr><tr><td><strong>FFT</strong></td><td>노드 월드(1구간=1일) → CT/AT 사각 전장. 월드에서 편성·파견</td><td>[문서: S02]</td></tr><tr><td><strong>CK3</strong></td><td>그랜드 전략 지도 하나에서 전투 해결(수동 전술 전장 없음)</td><td>[문서: S67, S68]</td></tr><tr><td><strong>Triangle / 창세기전 2</strong></td><td>세계 사건 지도(W)+지역 탐색(E)+전장(B) 3면</td><td>[문서: S05–S07, S66]</td></tr></tbody></table><p><strong>최고: Battle Brothers / FFT</strong> — 전략적 결정이 전술 결과에 그대로 이어지고, 전술 손실이 전략 경제로 반환.</p><p><strong>잔선 권고 [적용 제안]:</strong> genre-map-structure §10의 3지도 구조 채택 — S 노선도 / W 역간 원정 / B 하이트맵 전장. 전환 계약: S 선택은 이동이 아님, 전투 후 자동 강제 귀환 없음.</p><hr><h2 id="_5-세계-진화·반응성" tabindex="-1">5. 세계 진화·반응성 <a class="header-anchor" href="#_5-세계-진화·반응성" aria-label="Permalink to &quot;5. 세계 진화·반응성&quot;">​</a></h2><table tabindex="0"><thead><tr><th>게임</th><th>구조</th><th>근거</th></tr></thead><tbody><tr><td><strong>K-시스템</strong></td><td>World States: 핵심 인물의 생존·수감·납치 조건 → Town Override·스폰 변화. 무레벨스케일링</td><td>[문서: S80, S92]</td></tr><tr><td><strong>Battle Brothers</strong></td><td>절차 생성 지도+4종 위기가 고용 시장·보급망·해로를 바꿈. 미시: 부속시설 파괴→현지 생산품 소멸</td><td>[문서: S99, S100, S104]</td></tr><tr><td><strong>CK3</strong></td><td>인물·의견·비밀·계책·계승이 지속 시뮬레이션</td><td>[문서: S20, S25, S28]</td></tr><tr><td><strong>Triangle / FE / FFT</strong></td><td>서사 분기 중심(Triangle 신념·투표가 가장 정교)</td><td>[문서: S06, S07]</td></tr></tbody></table><p><strong>최고: K-시스템(World States) + BB(위기)의 조합.</strong></p><p><strong>잔선 권고 [적용 제안]:</strong> 두 속도 — ①작은 사건: 통로 안전·시장 물량·부속시설 상태 ②큰 사건: 주요 인물 생존·세력 전쟁 상태 전이. 유랑 밴드와 역 운영자에게 다른 반응. 전 세계 생산·전쟁 AI는 만들지 않는다.</p><hr><h2 id="_6-난이도-철학" tabindex="-1">6. 난이도 철학 <a class="header-anchor" href="#_6-난이도-철학" aria-label="Permalink to &quot;6. 난이도 철학&quot;">​</a></h2><table tabindex="0"><thead><tr><th>게임</th><th>철학</th><th>근거</th></tr></thead><tbody><tr><td><strong>K-시스템</strong></td><td>무레벨스케일링 + &#39;너는 특별하지 않다&#39;</td><td>[문서: S80, S82, S83]</td></tr><tr><td><strong>Battle Brothers</strong></td><td>스케일링 분해: 계약은 분대 강도 기준, 비계약 야영지는 문명 거리·시간</td><td>[문서: S97, S102]</td></tr><tr><td><strong>FE 각성</strong></td><td>Classic/Casual 모드 분리</td><td>[문서: S01]</td></tr><tr><td><strong>Triangle</strong></td><td>패배해도 EXP·Kudos 보존</td><td>[문서: S07]</td></tr><tr><td><strong>CK3</strong></td><td>난이도가 역할극 부담(스트레스)</td><td>[문서: S29, S30]</td></tr></tbody></table><p><strong>잔선 권고 [적용 제안]:</strong> ①무레벨스케일링 ②스케일 대상 명시 ③실패의 완충 — 부상·이탈은 회복 경로가 남는 선에서 ④난이도 시작 분화는 K-시스템식 결핍 조합.</p><hr><h2 id="_7-포획-모집" tabindex="-1">7. 포획/모집 <a class="header-anchor" href="#_7-포획-모집" aria-label="Permalink to &quot;7. 포획/모집&quot;">​</a></h2><table tabindex="0"><thead><tr><th>게임</th><th>구조</th><th>근거</th></tr></thead><tbody><tr><td><strong>K-시스템</strong></td><td>정식 동료 = 대화 가입비(3,000–7,500c). 무료 특수 동료·해방 후 합류. 모집≠일당: 기간제 경호 별도. 현상범 포획·인도가 수입+정치 자산. 지도자 납치가 세계 상태 변경 수단</td><td>[문서: S83, S87, S91–S93]</td></tr><tr><td><strong>Battle Brothers</strong></td><td>모집은 배경·레벨·급여에 따른 고용 시장. Manhunters는 포로 충원. Retinue 수행원은 명성 슬롯</td><td>[문서: S96, S98, S101]</td></tr><tr><td><strong>FE / FFT / Langrisser</strong></td><td>서사 합류·주점 고용·상점 용병</td><td>[문서: S01, S02, S11]</td></tr><tr><td><strong>CK3</strong></td><td>인물 목록·자문회 임명 — 사람 목록을 &#39;행동 가능한 업무 목록&#39;으로</td><td>[문서: S19, S27]</td></tr><tr><td><strong>창세기전/파랜드/Triangle</strong></td><td>서사 합류·설득</td><td>[문서: S05–S07, S09]</td></tr></tbody></table><p><strong>잔선 권고 [적용 제안]:</strong> ①모집 3경로: 구조→신뢰→가입 / 계약 인력 / 역 내 인력 시장 ②포획: 적 대표를 제압해 심문·인도·고용 협상 중 선택 ③비전투 조직 성장: BB Retinue 상당 ④고용 확인은 Langrisser 문법 — 비용·조건·불가 사유 확정 전 공개.</p><hr><h2 id="_8-종합-우선순위-잔선-구현-순서-권고" tabindex="-1">8. 종합 우선순위 (잔선 구현 순서 권고) <a class="header-anchor" href="#_8-종합-우선순위-잔선-구현-순서-권고" aria-label="Permalink to &quot;8. 종합 우선순위 (잔선 구현 순서 권고)&quot;">​</a></h2><ol><li><strong>P0 — 떠돌이 경제 한 바퀴:</strong> 3인 밴드+손수레+3일 식량 시작 → 계약 선택 → W 이동 → 조우 3카드 → B 수동 전술 → 정산 영수증(인물별 부상 포함)</li><li><strong>P0 — 부상 지속:</strong> BB 영구부상 문법. 부상이 다음 전투 시작 HP·명중에 이어짐.</li><li><strong>P1 — 세계 두 속도:</strong> 부속시설 상태 + 핵심 인물 상태 전이.</li><li><strong>P1 — 모집·조직:</strong> 관계 기반 동료 + 계약 인력 분리.</li><li><strong>P2 — 정착 선택:</strong> &#39;B1 정비실 운영권&#39; 수준에서 시작해 역 전체 주권은 후반.</li></ol><h2 id="_9-명시적으로-채택하지-않는-것" tabindex="-1">9. 명시적으로 채택하지 않는 것 <a class="header-anchor" href="#_9-명시적으로-채택하지-않는-것" aria-label="Permalink to &quot;9. 명시적으로 채택하지 않는 것&quot;">​</a></h2><ul><li>CK3식 전투 추상화·봉건 계승·거대 관계 그래프</li><li>BB 육각 격자·9AP·대규모 용병단 수치 (사각 3AP·3인 파티 유지)</li><li>K-시스템 초반 채굴 grind</li><li>Triangle식 &#39;모든 결과 미리 공개&#39;·FE식 자동 원상복구</li><li>전면 4X 세계 시뮬레이션</li></ul><h2 id="출처" tabindex="-1">출처 <a class="header-anchor" href="#출처" aria-label="Permalink to &quot;출처&quot;">​</a></h2><p>본문 인용 [S-ID]는 각 원문서의 sources.json 체계를 재사용: [S01–S14] REPORT.md, [S19–S33] ck3-ui-reference.md, [S40–S50·S70] bb-ui-reference.md, [S60–S74] genre-map-structure.md, [S80–S108] 내부 종합 조사 문서. 유니콘 오버로드·배너로드·신장의야망·태합입지전·삼국지는 조사 완료 후 본 매트릭스에 추가한다.</p>',46)])])}const c=r(a,[["render",s]]);export{b as __pageData,c as default};
